_N = [0]


def V(key, stem, correct, wrong, explanation, pearl, curveball, curveball_answer, stage, focus):
    """Build one vignette. `wrong` is a list of three (choice, why_wrong) pairs.
    The correct answer position rotates 0-3 so positions are spread evenly."""
    pos = _N[0] % 4
    _N[0] += 1
    choices = [w[0] for w in wrong]
    why = [w[1] for w in wrong]
    choices.insert(pos, correct)
    why.insert(pos, "Correct.")
    return {
        "topic": TOP[key][0], "concept_id": TOP[key][1],
        "stem": stem, "choices": choices, "answer": pos,
        "explanation": explanation, "why_wrong": why,
        "board_pearl": pearl, "curveball": curveball,
        "curveball_answer": curveball_answer,
        "learning_stage": stage, "focus": focus,
    }


